    """A model-free token estimate: four characters a token, rounded up."""
    return -(-len(text) // 4)


def _section(kind: SliceKind, entries: Sequence[PackEntry]) -> str:
    return f"// === {_HEADERS[kind]} ===\n" + "".join(e.render() for e in entries)


