    PackConfig,
    SliceKind,
    build_context_pack,
    estimate_tokens,
    store_contracts,
)

EXAMPLES = Path(__file__).resolve().parents[2] / "examples"

RING_H = """\
#define CAP 4
#define SLOTS (CAP * 2)

typedef struct {
    int buf[SLOTS];
    unsigned head, tail, count;
} ring_t;

/* Initialise an empty ring. */
void rb_init(ring_t *r);
int rb_push(ring_t *r, int v);
void log_full(int count);
"""

RING_C = """\
#include "ring.h"

/* Moves the tail one slot on. */
static void advance(ring_t *r) {
    r->tail = (r->tail + 1) % SLOTS; /* secret_body_marker */
}

/* Push v; returns 0 when full. */
int rb_push(ring_t *r, int v) {
    if (r->count == SLOTS) {
        log_full(r->count);
        return 0;
    }
    r->buf[r->tail] = v;
    advance(r);
    r->count++;
    return 1;
}

void rb_init(ring_t *r) {
    r->head = r->tail = r->count = 0;
}
"""

APP_C = """\
#include "ring.h"

int enqueue_all(ring_t *r, int n) {
    int stored = 0;
    for (int i = 0; i < n; i++) {
        if (!rb_push(r, i)) {
            break;
        }
        stored++;
    }
    return stored;
}

int main(void) {
    ring_t r;
    rb_init(&r);
    return rb_push(&r, 1);
}
"""

TEST_C = """\
#include "ring.h"

/* A full ring refuses another push. */
static void test_push_when_full(void) {
    ring_t r;
    rb_init(&r);
    for (int i = 0; i < SLOTS; i++) {
        rb_push(&r, i);
    }
    assert(rb_push(&r, 9) == 0);
}
"""

PROJECT: Mapping[str, str] = {
    "include/ring.h": RING_H,
    "src/ring.c": RING_C,
    "src/app.c": APP_C,
    "tests/test_ring.c": TEST_C,
    "README.md": "rb_push is documented here",
